#!/usr/bin/env bash
# Cloud Maker — cleanup of integration-test leftovers only.
# Operates only on identifiers generated by scripts/check_api.py.
set -euo pipefail

URI="qemu:///system"
IMAGE_DIR="/var/lib/libvirt/images/cloud-maker/api"
ASSUME_YES=false
DRY_RUN=false

usage() {
    cat <<'HELP'
Usage: ./scripts/cleanup.sh [--dry-run] [--yes]
  --dry-run   Only show test resources that would be deleted
  --yes       Do not ask for confirmation

Only cleans test resources made by scripts/check_api.py:
  cm-api-check-<12 lowercase hex digits>
  cm-api-oversized-<10 lowercase hex digits>
Does not touch other Cloud Maker VMs or the base Ubuntu image.
HELP
}

for arg in "$@"; do
    case "$arg" in
        --yes|-y) ASSUME_YES=true ;;
        --dry-run|-n) DRY_RUN=true ;;
        --help|-h) usage; exit 0 ;;
        *) printf 'Unknown argument: %s\n' "$arg" >&2; usage >&2; exit 2 ;;
    esac
done

is_test_vm() {
    [[ "$1" =~ ^cm-api-check-[0-9a-f]{12}$ || "$1" =~ ^cm-api-oversized-[0-9a-f]{10}$ ]]
}

is_test_file() {
    [[ "$1" =~ ^cm-api-check-[0-9a-f]{12}(\.qcow2|-seed\.iso)$ || "$1" =~ ^cm-api-oversized-[0-9a-f]{10}(\.qcow2|-seed\.iso)$ ]]
}

# Verify privileges and connectivity before collecting targets.
sudo -v
sudo virsh -c "$URI" list --all >/dev/null

vms=()
while IFS= read -r name; do
    if is_test_vm "$name"; then
        vms+=("$name")
    fi
done < <(sudo virsh -c "$URI" list --all --name)

files=()
if sudo test -d "$IMAGE_DIR"; then
    while IFS= read -r filename; do
        if is_test_file "$filename"; then
            files+=("$filename")
        fi
    done < <(sudo find "$IMAGE_DIR" -mindepth 1 -maxdepth 1 -type f -printf '%f\n')
fi

printf 'Cloud Maker: cleanup of integration-test leftovers\n'
printf 'Found test VMs: %s; test files: %s\n' "${#vms[@]}" "${#files[@]}"

for name in "${vms[@]}"; do printf '  VM:   %s\n' "$name"; done
for name in "${files[@]}"; do printf '  File: %s/%s\n' "$IMAGE_DIR" "$name"; done

if (( ${#vms[@]} == 0 && ${#files[@]} == 0 )); then
    printf '[OK] Nothing to clean.\n'
    exit 0
fi

if "$DRY_RUN"; then
    printf '[OK] Dry run: nothing was changed.\n'
    exit 0
fi

if ! "$ASSUME_YES"; then
    printf '\nWARNING: matched test VMs will be forcibly stopped if active.\n'
    read -r -p 'Delete ONLY these test resources? [y/N] ' reply
    if [[ "$reply" != y && "$reply" != Y ]]; then
        printf 'Cancelled.\n'
        exit 0
    fi
fi

# Remove registered test domains first; do not delete attached disks of a live VM.
failed=0
for name in "${vms[@]}"; do
    printf 'Removing test VM %s...\n' "$name"
    if sudo virsh -c "$URI" domstate "$name" 2>/dev/null | grep -qv '^shut off$'; then
        if ! sudo virsh -c "$URI" destroy "$name" >/dev/null; then
            printf '[ERROR] Could not stop %s; keeping its files.\n' "$name" >&2
            failed=1
            continue
        fi
    fi
    if ! sudo virsh -c "$URI" undefine "$name" >/dev/null; then
        printf '[ERROR] Could not undefine %s; keeping its files.\n' "$name" >&2
        failed=1
    fi
done

# Re-check: never delete a disk belonging to a still registered test domain.
for filename in "${files[@]}"; do
    if [[ "$filename" == *-seed.iso ]]; then
        domain="${filename%-seed.iso}"
    else
        domain="${filename%.qcow2}"
    fi
    if sudo virsh -c "$URI" list --all --name | grep -Fxq -- "$domain"; then
        printf '[SKIP] %s belongs to a still registered VM.\n' "$filename"
        failed=1
        continue
    fi
    # The filename is strictly validated and find only selected regular files.
    if sudo rm -f -- "$IMAGE_DIR/$filename"; then
        printf '[OK] Removed %s\n' "$filename"
    else
        printf '[ERROR] Could not remove %s\n' "$filename" >&2
        failed=1
    fi
done

if (( failed )); then
    printf '[FAIL] Some test resources could not be cleaned.\n' >&2
    exit 1
fi
printf '[PASS] Test resources cleaned successfully.\n'
